93	
94	    /** A pasted line, read: the person it names and the claim's fields (no date: the sheet's entry date,
95	     *  else its today; no ref: no reference). */
96	    private record Line(Person person, BigDecimal amount, LocalDate date, String note, String ref) {
97	    }
98	
99	    private final PersonRepository people;
100	    private final ClaimRepository claims;
101	    private final ClaimService claimService;
102	
103	    public PasteClaimsService(PersonRepository people, ClaimRepository claims, ClaimService claimService) {
104	        this.people = people;
105	        this.claims = claims;
106	        this.claimService = claimService;
107	    }
108	
109	    /** Add a draft claim per pasted line of name,amount,date,note, in order. Every line is read first,
110	     *  then each is added with the claim form's rules; one change: when any line is refused, nothing is
111	     *  added and nothing is written. Blank lines are skipped; a paste with no lines is refused, as is one
112	     *  giving a reference already used on the sheet or by an earlier line, compared without regard to case. */
113	    @Transactional
114	    public List<Claim> paste(String sheetId, String user, String text) {
115	        List<Line> lines = new ArrayList<>();
116	        Set<String> refs = new HashSet<>();
117	        int number = 0;
118	        for (String raw : text.split("\\r?\\n")) {
119	            number++;
120	            if (raw.isBlank()) continue;
121	            Line line = read(sheetId, raw, number);
122	            if (line.ref() != null && (!refs.add(line.ref().toLowerCase(Locale.ROOT))
123	                    || claims.refUsed(sheetId, line.ref(), null))) {
124	                throw refused(number, "the reference '" + line.ref() + "' is already used");
125	            }
126	            lines.add(line);
127	        }
128	        if (lines.isEmpty()) {
129	            throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_CONTENT, "Paste at least one line.");
130	        }
131	        List<Claim> added = new ArrayList<>();
132	        for (Line line : lines) {
133	            added.add(claimService.add(sheetId, user, line.person().getId(), line.amount(), line.date(), line.note(), null,
134	                    line.ref(), null));
135	        }
136	        return added;
137	    }
138	
139	    /** A line of name,amount,date,note; the note may hold commas, the date may be blank and the note absent.
140	     *  A note ending in ' #<reference>' gives the claim that reference, which is not part of the note. */
141	    private Line read(String sheetId, String raw, int number) {
142	        String[] fields = raw.split(",", 4);
143	        if (fields.length < 2) throw refused(number, "it needs at least a name and an amount");
144	        String name = fields[0].trim();
145	        Person person = name.isEmpty() ? null
146	                : people.findByNameOrAlias(sheetId, Person.keyOf(name)).orElse(null);
147	        if (person == null) throw refused(number, "no one on the sheet is named '" + name + "'");
148	        BigDecimal amount;
149	        try {
150	            amount = new BigDecimal(fields[1].trim());
151	        } catch (NumberFormatException e) {
152	            throw refused(number, "the amount is not a number");
153	        }
154	        if (amount.scale() > 2 || amount.precision() - amount.scale() > 10) {
155	            throw refused(number, "the amount has more than two decimals or ten digits");
156	        }
157	        LocalDate date = null;
158	        if (fields.length > 2 && !fields[2].isBlank()) {
159	            try {
160	                date = LocalDate.parse(fields[2].trim());
161	            } catch (DateTimeParseException e) {
162	                throw refused(number, "the date is not a date (yyyy-mm-dd)");
163	            }
164	        }
165	        String note = fields.length > 3 ? fields[3].trim() : "";
166	        String ref = null;
167	        int hash = note.lastIndexOf(" #");
168	        if (hash >= 0) {
169	            ref = ClaimService.refOf(note.substring(hash + 2));
170	            note = note.substring(0, hash).trim();
171	        }
172	        if (ref != null && ref.length() > 220) throw refused(number, "the reference is longer than 220 characters");
173	        if (note.length() > 1000) throw refused(number, "the note is longer than 1000 characters");
174	        return new Line(person, amount, date, note, ref);
175	    }
176	
177	    private static ResponseStatusException refused(int number, String why) {
178	        return new ResponseStatusException(HttpStatus.UNPROCESSABLE_CONTENT, "Line " + number + ": " + why + ".");
179	    }
180	}
