248	     *  with no patrons is left out. */
249	    @Transactional(readOnly = true)
250	    public Map<Long, List<Long>> patronIds(String sheetId) {
251	        Map<Long, List<Long>> by = new LinkedHashMap<>();
252	        for (PersonPatron patron : patrons.findBySheetIdOrderByIdAsc(sheetId)) {
