264	    /** Name another person on the sheet as one of the person's patrons; refused for the person
265	     *  themselves and for someone already their patron. */
266	    @Transactional
267	    public Person addPatron(String sheetId, String user, long id, long patronId) {
268	        Person person = people.findByIdAndSheetId(id, sheetId)
269	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person."));
270	        Person patron = people.findByIdAndSheetId(patronId, sheetId)
271	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such patron."));
272	        if (person.getId().equals(patron.getId())) {
273	            throw new ResponseStatusException(HttpStatus.CONFLICT, "A person cannot be their own patron.");
274	        }
275	        if (patrons.existsByPersonIdAndPatronId(person.getId(), patron.getId())) {
276	            throw alreadyPatron();
277	        }
278	        try {
279	            patrons.saveAndFlush(new PersonPatron(sheetId, person.getId(), patron.getId()));
280	        } catch (DataIntegrityViolationException raced) {
281	            // Another user named the same patron at the same moment.
282	            throw alreadyPatron();
283	        }
284	        audit.recordOnCommit("PATRON_ADDED sheet=" + sheetId + " by=" + user
285	                + " name=" + person.getName() + " patron=" + patron.getName());
286	        return person;
287	    }
