302	    /** Start (true) or stop (false) the user watching the person; when the user already does as asked,
303	     *  nothing changes. A user who starts watching again is told after those watching meanwhile. */
304	    @Transactional
305	    public Person watch(String sheetId, String user, long id, boolean on) {
306	        Person person = people.findByIdAndSheetId(id, sheetId)
307	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person."));
308	        Optional<PersonWatch> watching = watches.findByPersonIdAndUserName(person.getId(), user);
309	        if (on == watching.isPresent()) return person;
310	        if (on) {
311	            try {
312	                watches.saveAndFlush(new PersonWatch(sheetId, person.getId(), user));
313	            } catch (DataIntegrityViolationException raced) {
314	                // The same user started watching from another screen at the same moment.
315	                throw new ResponseStatusException(HttpStatus.CONFLICT, "You already watch this person.");
316	            }
317	        } else {
318	            watches.delete(watching.get());
319	            watches.flush();
320	        }
321	        audit.recordOnCommit((on ? "PERSON_WATCHED" : "PERSON_UNWATCHED") + " sheet=" + sheetId + " by=" + user
322	                + " name=" + person.getName());
323	        return person;
324	    }
