336	    /** Add a person to the sheet with a contact (blank or null: none); refused when the name is used as a
337	     *  name or alias on the sheet or on another sheet of its tree, or when another person on the sheet has
338	     *  the same contact. */
339	    @Transactional
340	    public Person add(String sheetId, String user, String name, Grade grade, Integer terms, String contact) {
341	        sheets.load(sheetId);
342	        if (people.existsBySheetIdAndNameKey(sheetId, Person.keyOf(name))
343	                || aliases.existsBySheetIdAndAliasKey(sheetId, Person.keyOf(name))) {
344	            throw nameInUse();
345	        }
346	        if (tree.usedElsewhere(sheetId, name)) {
347	            throw nameInUseInTree();
348	        }
349	        String contactKey = Person.contactOf(contact);
350	        if (contactKey != null && people.existsBySheetIdAndContact(sheetId, contactKey)) {
351	            throw contactInUse();
352	        }
353	        Rollup.Snapshot before = rollup.snapshot(sheetId);
354	        Person fresh = new Person(sheetId, name, grade, sheets.today(sheetId));
355	        fresh.setTerms(terms);
356	        fresh.setContact(contactKey);
357	        Person person = save(fresh);
358	        recordChange("PERSON_ADDED", user, person, (terms == null ? "" : " terms=" + terms)
359	                + (contactKey == null ? "" : " contact=" + contactKey));
360	        rollup.recordChanges(user, before);
361	        return person;
362	    }
363	
364	    /** Change a person's name and give them a grade from a from-date (none: the sheet's today), keeping
365	     *  the grades they were given from other dates; refused when someone has saved the person since
366	     *  the editor loaded this version of them, or when another person on the sheet has the contact
367	     *  given (blank or null: none). Refused too when the name, or any of the person's aliases, is used on
368	     *  another sheet of the sheet's tree, so a person who clashes can only be edited by a rename that
369	     *  leaves them clashing no more. */
370	    @Transactional
371	    public Person update(String sheetId, String user, long id, long version, String name, Grade grade,
372	            LocalDate gradeFrom, Integer terms, String contact) {
373	        Person person = people.findByIdAndSheetId(id, sheetId)
374	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person."));
375	        if (person.getVersion() != version) {
376	            throw changedMeanwhile();
377	        }
378	        if (people.existsBySheetIdAndNameKeyAndIdNot(sheetId, Person.keyOf(name), id)
379	                || aliases.existsBySheetIdAndAliasKey(sheetId, Person.keyOf(name))) {
380	            throw nameInUse();
381	        }
382	        Set<String> elsewhere = tree.keysElsewhere(sheetId, id);
383	        if (elsewhere.contains(Person.keyOf(name))
384	                || person.getAliases().stream().map(Person::keyOf).anyMatch(elsewhere::contains)) {
385	            throw nameInUseInTree();
386	        }
387	        String contactKey = Person.contactOf(contact);
388	        if (contactKey != null && people.existsBySheetIdAndContactAndIdNot(sheetId, contactKey, id)) {
389	            throw contactInUse();
390	        }
391	        Rollup.Snapshot before = rollup.snapshot(sheetId);
392	        boolean contactChanged = !Objects.equals(person.getContact(), contactKey);
393	        boolean termsChanged = !Objects.equals(person.getTerms(), terms);
394	        person.setName(name);
395	        person.setGrade(grade, gradeFrom != null ? gradeFrom : sheets.today(sheetId), sheets.today(sheetId));
396	        person.setTerms(terms);
397	        person.setContact(contactKey);
398	        Person saved = save(person);
399	        recordChange("PERSON_EDITED", user, saved, (termsChanged ? " terms=" + (terms == null ? "" : terms) : "")
400	                + (contactChanged ? " contact=" + (contactKey == null ? "" : contactKey) : ""));
401	        rollup.recordChanges(user, before);
402	        return saved;
403	    }
404	
405	    /** Give a person another name they are found by; refused when blank, or when it equals, as names
406	     *  are compared, any name or alias on the sheet or on another sheet of its tree. */
407	    @Transactional
408	    public Person addAlias(String sheetId, String user, long id, String alias) {
409	        Person person = people.findByIdAndSheetId(id, sheetId)
410	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person."));
411	        if (alias == null || alias.isBlank()) {
412	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "Enter an alias.");
413	        }
414	        String key = Person.keyOf(alias);
415	        if (people.existsBySheetIdAndNameKey(sheetId, key) || aliases.existsBySheetIdAndAliasKey(sheetId, key)) {
416	            throw nameInUse();
417	        }
418	        if (tree.usedElsewhere(sheetId, alias)) {
419	            throw nameInUseInTree();
420	        }
421	        person.addAlias(alias);
422	        Person saved = save(person);
423	        audit.recordOnCommit("PERSON_ALIAS_ADDED sheet=" + sheetId + " by=" + user
424	                + " name=" + saved.getName() + " alias=" + alias.trim());
425	        return saved;
426	    }
