428	    /** Retire a person from a date, the sheet's today when none is given. Once the sheet's today reaches
429	     *  the date, their open claims count in no live total, unless a statement binds them; their settled
430	     *  claims still count. Claims dated after the date can no longer be added to them. */
431	    @Transactional
432	    public Person retire(String sheetId, String user, long id, LocalDate from) {
433	        Person person = people.findByIdAndSheetId(id, sheetId)
434	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person."));
435	        LocalDate dated = from != null ? from : sheets.today(sheetId);
436	        Rollup.Snapshot before = rollup.snapshot(sheetId);
437	        person.setRetiredFrom(dated, sheets.today(sheetId));
438	        Person saved = save(person);
439	        audit.recordOnCommit("PERSON_RETIRED sheet=" + sheetId + " by=" + user
440	                + " name=" + saved.getName() + " from=" + dated);
441	        rollup.recordChanges(user, before);
442	        return saved;
443	    }
444	
445	    /** Put a hold on a person from a date (none: the sheet's today) to a date (none: no end); refused
446	     *  when it ends before it starts. Their open claims dated within it count in no live total, unless
447	     *  a statement binds them; their settled claims still count. */
448	    @Transactional
449	    public Person hold(String sheetId, String user, long id, LocalDate from, LocalDate to) {
450	        Person person = people.findByIdAndSheetId(id, sheetId)
451	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person."));
452	        LocalDate dated = from != null ? from : sheets.today(sheetId);
453	        if (to != null && to.isBefore(dated)) {
454	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "A hold cannot end before it starts.");
455	        }
456	        Rollup.Snapshot before = rollup.snapshot(sheetId);
457	        person.hold(dated, to, sheets.today(sheetId));
458	        Person saved = save(person);
459	        audit.recordOnCommit("PERSON_HELD sheet=" + sheetId + " by=" + user + " name=" + saved.getName()
460	                + " from=" + dated);
461	        rollup.recordChanges(user, before);
462	        return saved;
463	    }
464	
465	    /** The person's audit line, with the grade in force on the sheet's today, then the fields given. */
466	    private void recordChange(String event, String user, Person person, String fields) {
467	        audit.recordOnCommit(event + " sheet=" + person.getSheetId() + " by=" + user
468	                + " name=" + person.getName() + " grade=" + person.gradeOn(sheets.today(person.getSheetId()))
469	                + fields);
470	    }
471	
472	    private Person save(Person person) {
473	        try {
474	            return people.saveAndFlush(person);
475	        } catch (OptimisticLockingFailureException raced) {
476	            // Another user saved the same person at the same moment.
477	            throw changedMeanwhile();
478	        } catch (DataIntegrityViolationException raced) {
479	            // Another user took the same name, or the same contact, at the same moment.
480	            String cause = String.valueOf(raced.getMostSpecificCause().getMessage()).toUpperCase(Locale.ROOT);
481	            throw cause.contains("PERSON_SHEET_CONTACT") ? contactInUse() : nameInUse();
482	        }
483	    }
484	
485	    private static ResponseStatusException changedMeanwhile() {
486	        return new ResponseStatusException(HttpStatus.PRECONDITION_FAILED,
487	                "Someone else has saved this person since it was opened.");
488	    }
489	
490	    private static ResponseStatusException contactInUse() {
491	        return new ResponseStatusException(HttpStatus.CONFLICT, "That contact is already in use on the sheet.");
492	    }
493	
494	    private static ResponseStatusException nameInUseInTree() {
495	        return new ResponseStatusException(HttpStatus.CONFLICT, "That name is already in use on a sheet of this sheet's tree.");
496	    }
497	
498	    private static ResponseStatusException nameInUse() {
499	        return new ResponseStatusException(HttpStatus.CONFLICT, "That name is already in use on the sheet.");
500	    }
501	}
